/**
 * @param {object} params
 * @param {Array<object>} [params.sections] — 未指定時は `DEFAULT_REVIEW_SECTIONS` を使用
 *   （既存の関数シグネチャ/戻り値は無変更）。
 */
export function buildPreShipApprovalReview({
  worktreePath,
  branch,
  baseBranch = 'main',
  planPath,
  planChecklist = '完了',
  worktreeStatus = 'clean',
  qualityGate = 'レビュー作成時に実際の結果を記入',
  testVerify = 'レビュー作成時に実際の結果を記入',
  draftPr = '未生成',
  gitLog = '',
  commitCount = null,
  commitRange = null,
  latestCommit = null,
  prUrl = '未生成',
  prStatus = 'Draft PR 生成前',
  mergeStatus = '承認前',
  ciStatus = '承認前',
  changedFilesTree = '(収集が必要)',
  changedRows = [],
  sections = DEFAULT_REVIEW_SECTIONS,
} = {}) {
  return renderTemplateFromSections(sections, {
    worktreePath,
    branch,
    baseBranch,
    planPath,
    planChecklist,
    worktreeStatus,
    qualityGate,
    testVerify,
    draftPr,
    gitLog,
    commitCount,
    commitRange,
    latestCommit,
    prUrl,
    prStatus,
    mergeStatus,
    ciStatus,
    changedFilesTree,
    changedRows,
  });
}

export function buildPostApprovalCompletionReport({
  result = {},
  cleanup = true,
  cleanedUp = false,
  cleanupResult = null,
  wtPath = null,
  postMergeMainStatus = null,
} = {}) {
  const cr = cleanupResult ?? {};
  const mergedSituation = result.merged
    ? 'Merged'
    : result.pending
      ? 'Open / Pending'
      : 'Not merged';
  const cleanupSituation = cleanup
    ? cleanedUp
      ? 'completed'
      : cr.ok === false
        ? 'partial / failed after merge'
        : 'attempted / unknown'
    : 'skipped (--no-cleanup)';
  const branchCleanup = result.merged
    ? 'remote delete requested; local cleanup handled by cleanup-worktree when enabled'
    : 'not performed';
  const mainStatus = cr.sync_status || (cleanup ? 'not reported' : 'not run');
  const changedTree = result.changed_files_tree || buildFileTree(result.changed_files || []);

  return [
    '# PR 承認後の完了報告',
    '## 1. PR',
    `- PR URL: ${valueOrDash(result.prUrl)}`,
    `- PR Merged 状況: ${mergedSituation}`,
    `- Merge commit / squash commit: ${valueOrDash(result.sha)}`,
    `- CI status: ${result.merged ? 'merge accepted by GitHub; detailed CI status not collected' : 'pending / not collected'}`,
    '',
    '## 2. Cleanup 状況',
    `- Worktree cleanup: ${cleanupSituation}${wtPath ? ` (${wtPath})` : ''}`,
    `- Branch cleanup: ${branchCleanup}`,
    `- Remote branch cleanup: ${result.merged ? 'delete requested when auto-merge ran' : 'not performed'}`,
    `- main への ff(Fast-Forward) 状況: ${mainStatus}`,
    '',
    '## 3. 反映されたファイル',
    '```text',
    changedTree,
    '```',
    '',
    '## 4. 残りの対応',
    `- 残作業: ${result.pending ? 'CI/レビュー通過後に merge を再試行または手動確認' : 'なし'}`,
    `- 手動対応が必要な項目: ${cr.ok === false ? valueOrDash(cr.hint) : 'なし'}`,
    `- 次セッションへの引き継ぎ事項: ${postMergeMainStatus?.status === 'dirty' ? `main dirty 状態の確認が必要 (${postMergeMainStatus.dirty_paths?.join(', ') || 'paths unknown'})` : 'なし'}`,
    '',
    '## 5. 問題 / 改善メモ',
    `- 発生した問題: ${Array.isArray(result.warnings) && result.warnings.length ? result.warnings.join('; ') : 'なし'}`,
    `- 回避策(ワークアラウンド): ${cr.hint || 'なし'}`,
    '- システム/プロセスに反映したい改善点:',
  ].join('\n');
}
